create table if not exists public.aura_profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'patient' check(role in('patient','clinician')),display_name text,preferred_language text default 'en',created_at timestamptz not null default now());create table if not exists public.health_events(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,payload jsonb not null default '{}'::jsonb,client_created_at timestamptz not null,idempotency_key uuid not null unique,created_at timestamptz not null default now());alter table public.aura_profiles enable row level security;alter table public.health_events enable row level security;grant select,insert,update on public.aura_profiles to authenticated;grant select,insert,update on public.health_events to authenticated;create policy "profile_select_own" on public.aura_profiles for select to authenticated using((select auth.uid())=id);create policy "profile_insert_own" on public.aura_profiles for insert to authenticated with check((select auth.uid())=id);create policy "profile_update_own" on public.aura_profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);create policy "events_select_own" on public.health_events for select to authenticated using((select auth.uid())=user_id);create policy "events_insert_own" on public.health_events for insert to authenticated with check((select auth.uid())=user_id);create policy "events_update_own" on public.health_events for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);